import{_ as e,o as t,c as n,a2 as s}from"./chunks/framework.Ch4PdLd_.js";const k=JSON.parse('{"title":"Plan 模式","description":"","frontmatter":{},"headers":[],"relativePath":"guide/plan-mode.md","filePath":"guide/plan-mode.md"}'),i={name:"guide/plan-mode.md"};function d(l,a,o,p,r,c){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="plan-模式" tabindex="-1">Plan 模式 <a class="header-anchor" href="#plan-模式" aria-label="Permalink to &quot;Plan 模式&quot;">​</a></h1><p>Plan 模式让 nek 先调研、澄清需求、写出计划，经你审阅批准后再切回 Agent 模式实施。适合改动范围大、方案有取舍、或者你想先看思路再动手的任务。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：/plan 给登录接口加限流</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  Plan 模式：读代码、搜索、必要时提问（ask_question）</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  create_plan：计划写入 .nek/plans/xxx.plan.md，完整计划显示在对话记录里</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  审阅面板：Implement / Fresh context / Keep planning / Exit Plan mode</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼ 选择 Implement</span></span>
<span class="line"><span>  切到 Agent 模式，计划的 todos 写入 Todo 列表，开始实施</span></span></code></pre></div><h2 id="两种模式" tabindex="-1">两种模式 <a class="header-anchor" href="#两种模式" aria-label="Permalink to &quot;两种模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Agent 模式（默认）</th><th>Plan 模式</th></tr></thead><tbody><tr><td>目的</td><td>完成任务</td><td>调研并写计划</td></tr><tr><td><code>edit</code> / <code>write</code></td><td>任意文件</td><td><strong>只能改 Markdown 文件</strong>（<code>.md</code>、<code>.markdown</code>）</td></tr><tr><td>子代理</td><td>按类型的工具集</td><td>只读</td></tr><tr><td><code>create_plan</code> / <code>update_plan</code></td><td>调用会报错</td><td>可用</td></tr><tr><td>输入框</td><td>普通边框</td><td>专用边框颜色，常驻 <code>PLAN</code> 标记</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Plan 模式不是沙箱</p><p>Plan 模式只在工具层面限制了 <code>edit</code> 和 <code>write</code> 的目标文件类型，<code>bash</code> 等其他工具仍然可用，模型被指示只做调研。不要把 Plan 模式当作安全边界，见 <a href="/nekcode/guide/security">安全使用</a>。</p></div><h2 id="enter" tabindex="-1">进入和退出 <a class="header-anchor" href="#enter" aria-label="Permalink to &quot;进入和退出 {#enter}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>效果</th></tr></thead><tbody><tr><td><code>/plan</code></td><td>安静地进入 Plan 模式（已在 Plan 模式时什么也不做）</td></tr><tr><td><code>/plan &lt;需求&gt;</code></td><td>进入 Plan 模式并提交一个规划请求（或对现有计划的修改请求）</td></tr><tr><td><code>Alt+M</code></td><td>在 Agent 和 Plan 之间切换（可在 <code>nek.yaml</code> 中修改，见下文）</td></tr><tr><td><code>nek --plan</code></td><td>以 Plan 模式启动</td></tr><tr><td><code>/agent</code></td><td>退出 Plan 模式回到 Agent，<strong>不</strong>开始实施</td></tr></tbody></table><p><code>/plan</code> 是幂等的“进入”，不会把你切回 Agent；退出请用 <code>/agent</code> 或 <code>Alt+M</code>。</p><h3 id="switch-mode" tabindex="-1">模型提议切换模式 <a class="header-anchor" href="#switch-mode" aria-label="Permalink to &quot;模型提议切换模式 {#switch-mode}&quot;">​</a></h3><p>模型可以调用 <code>switch_mode</code> 提议切换，例如在 Agent 模式下发现任务需要先规划，或在 Plan 模式下你明确说“现在就开始写代码”。每次提议都会弹出确认，<strong>必须由你同意</strong>才会切换。你拒绝后，模型不会为同一个任务反复提议。</p><p>nek 的提示词要求模型只在模式明显不合适时才提议：任务大本身不是切换到 Plan 的理由；用户要求出计划、或者存在只有你能做的、会显著改变实现的决定时才会提议。</p><h2 id="create" tabindex="-1">写计划 <a class="header-anchor" href="#create" aria-label="Permalink to &quot;写计划 {#create}&quot;">​</a></h2><p>在 Plan 模式下，模型会：</p><ol><li>用 <code>read</code>、<code>grep</code>、<code>ast_grep</code>、只读子代理等调研代码；</li><li>只在存在会改变计划的决定时，用 <code>ask_question</code> 向你提问；</li><li>调用 <code>create_plan</code>，参数包括计划名称、一两句话的概要（overview）、计划正文和一组 todos。</li></ol><p>计划保存为 <code>.nek/plans/&lt;名称&gt;_&lt;随机id&gt;.plan.md</code>，格式如下：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: Login rate limit</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">overview: 用中间件按 IP 限制登录接口每分钟 20 次，超限返回 429。</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">todos:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id: middleware</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    content: 新增 rateLimit 中间件</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id: wire</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    content: 在 /login 路由上启用</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id: tests</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    content: 补充超限与重置窗口的测试</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Login rate limit</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 方案</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span></code></pre></div><ul><li>计划 ID 就是文件名去掉 <code>.plan.md</code> 的部分，例如 <code>login-rate-limit_3fa2c1</code>。</li><li>一个会话可以有多份计划。<code>create_plan</code> 不带 <code>plan_id</code> 时总是新建；带 <code>plan_id</code> 时原位整份重写那份计划。</li><li>计划目录可以在 <code>nek.yaml</code> 里改（<code>plan.dir</code>，默认 <code>.nek/plans</code>）。</li></ul><h2 id="review" tabindex="-1">审阅计划 <a class="header-anchor" href="#review" aria-label="Permalink to &quot;审阅计划 {#review}&quot;">​</a></h2><p>计划写好后：</p><ul><li><strong>完整计划</strong>作为一条消息追加到对话记录里，可以像普通消息一样翻页（<code>PageUp</code>/<code>PageDown</code>、鼠标滚轮），普通模式下也在终端回滚记录里。这条预览只用于显示，不会发给模型。</li><li>输入框位置换成一个紧凑的<strong>审阅面板</strong>，标题为 “Implement this plan?”：</li></ul><table tabindex="0"><thead><tr><th>选项</th><th>效果</th></tr></thead><tbody><tr><td><strong>Implement</strong></td><td>切到 Agent 模式，把计划的 todos 写入 Todo 列表（第一项为进行中），并发送“Implement the plan.”开始实施</td></tr><tr><td><strong>Fresh context</strong></td><td>开一个新会话来实施：新会话的第一条消息是计划全文。面板会显示当前上下文已用的百分比，上下文快满时选它</td></tr><tr><td><strong>Keep planning</strong></td><td>留在 Plan 模式，继续和模型讨论、修改计划</td></tr><tr><td><strong>Exit Plan mode</strong></td><td>切回 Agent 模式，但不开始实施</td></tr></tbody></table><p>按 <code>Escape</code> 关闭面板，什么也不改变。</p><p>批准只对你审阅的那个<strong>修订版本</strong>有效。计划在审阅后被修改（包括你在编辑器里手动改了文件），需要重新提交审阅。</p><h3 id="用命令审阅或实施" tabindex="-1">用命令审阅或实施 <a class="header-anchor" href="#用命令审阅或实施" aria-label="Permalink to &quot;用命令审阅或实施&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/plans</code></td><td>选择一份已保存的计划并预览</td></tr><tr><td><code>/nek-build [plan_id]</code></td><td>批准并实施一份已审阅的计划修订版本（不带参数时选择）</td></tr><tr><td><code>/nek-build [plan_id] --fresh</code></td><td>同上，但在新会话里实施</td></tr></tbody></table><h2 id="revise" tabindex="-1">修改计划 <a class="header-anchor" href="#revise" aria-label="Permalink to &quot;修改计划 {#revise}&quot;">​</a></h2><p>在 Plan 模式下继续和模型对话（或用 <code>/plan &lt;修改意见&gt;</code>），模型会修订计划：</p><ul><li><strong>增量修订</strong>（常见情况）：模型先 <code>read</code> 计划文件，用 <code>edit</code> 只改需要改的段落（包括 frontmatter 里的 <code>overview</code> 和 <code>todos</code>），再调用 <code>update_plan</code> 提交审阅。nek 以磁盘上的文件为准：正文确实变了才把修订号加 1，并且只把 diff 返回给模型。</li><li><strong>整份重写</strong>：换了任务，或者你明确要求重写时，模型用 <code>create_plan</code> 加 <code>plan_id</code>。</li></ul><p>你也可以自己用编辑器修改 <code>.plan.md</code> 文件。nek 不监听文件变化，改完后让模型调用 <code>update_plan</code>（例如告诉它“我改了计划文件，请重新提交审阅”），变化才会同步进会话并重新审阅。</p><h3 id="再次进入-plan-模式" tabindex="-1">再次进入 Plan 模式 <a class="header-anchor" href="#再次进入-plan-模式" aria-label="Permalink to &quot;再次进入 Plan 模式&quot;">​</a></h3><p>再次进入 Plan 模式时，之前的计划只作为参考：模型会比较最新的需求和现有计划。</p><ul><li>是<strong>不同的任务</strong>：写一份新计划；</li><li>是<strong>同一个任务</strong>：修订现有计划并删除过时的内容；</li><li>只有存在真正未决定的问题时才重新提问，修订后重新提交审阅。</li></ul><h2 id="实施之后" tabindex="-1">实施之后 <a class="header-anchor" href="#实施之后" aria-label="Permalink to &quot;实施之后&quot;">​</a></h2><p>批准后没有单独的“执行阶段”：nek 就是在 Agent 模式下照常工作，计划的 todos 变成普通的 Todo 列表。按 <code>Escape</code> 像中止任何运行一样中止实施，Todo 列表保持原样，计划文件和已完成的进度都保留。</p><p>中断会撤销尚未生效的批准。旧的 todos、旧的批准、后台子代理的完成通知都不会自动恢复旧计划或覆盖你的新需求。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p><code>~/.nek/agent/nek.yaml</code>（或受信任项目的 <code>.nek/nek.yaml</code>）：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.nek/plans</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 计划文件目录，相对于工作目录</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  shortcut</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">alt+m</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 切换 Plan 模式的快捷键</span></span></code></pre></div><p>见 <a href="/nekcode/reference/nek-yaml">nek.yaml</a>。</p><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li>计划文件是普通 Markdown，可以提交到仓库，作为设计记录。不想提交的话把 <code>.nek/plans/</code> 加进 <code>.gitignore</code>。</li><li>上下文已经很满时，选 <strong>Fresh context</strong> 在干净的会话里实施，效果通常更好。</li><li>计划里的 todos 应该是具体、可执行的步骤，这样实施时的 Todo 列表才有参考价值。</li></ul>`,42)])])}const g=e(i,[["render",d]]);export{k as __pageData,g as default};
